arguments.command:
npx playwright-core@latest screenshot --browser=chromium --viewport-size=1280,800 --wait-for-timeout=3000 http://localhost:8080/index.html /app/output/preview-desktop.png 2>&1 || echo "playwright not available, trying puppeteer..."
if [ ! -f /app/output/preview-desktop.png ]; then
  node -e "
    const puppeteer = require('puppeteer');
    (async () => {
      const browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox'] });
      const page = await browser.newPage();
      await page.setViewport({ width: 1280, height: 800 });
      await page.goto('http://localhost:8080/index.html', { waitUntil: 'networkidle2' });
      await page.waitForTimeout(3000);
      await page.screenshot({ path: '/app/output/preview-desktop.png', fullPage: false });
      await browser.close();
    })();
  " 2>&1 || echo "puppeteer not available either"
fi
ls -la /app/output/preview-desktop.png 2>/dev/null || echo "No screenshot tool available"
